// File 1: Strong Definitions (Symbol Table Entries)
int global_data = 10;

void engine_init(void) { /* ... */ }

// File 2: External References (Requires Resolution by Linker)

// 'extern' forces the linker to find definition in another symbol table
extern int global_data;
extern void engine_init(void);

void setup_system() {
    engine_init();

    // Reference resolves to definition in File 1
    if (global_data == 10) {
        // ...
    }
}
// Symbol Table Status during Linking:
// global_data: UNDEF (File 2) -> GLOBAL (File 1)
// engine_init: UNDEF (File 2) -> GLOBAL (File 1)
